window.Game=window.Game||{};
(()=>{
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),T={food:'口粮',water:'饮用水',bandage:'绷带',medkit:'医疗包',medicine:'药剂',scrap:'干净布料',stabilizer:'稳定剂',suppressant:'抑制剂',ammo:'9mm 弹药',pistol:'旧式手枪',toolkit:'撬锁工具',route_note:'路线便笺',pass:'通行证',lab_note:'配比记录'},S={combat:'战斗',survival:'生存',science:'科研',social:'交涉',stealth:'潜行',mechanical:'机械'};
function view(screen){for(const el of document.querySelectorAll('.screen'))el.hidden=true;$(screen).hidden=false;const hb=$('home-button');hb.hidden=screen==='home'||screen==='ending';}
function bar(label,value,max,numeric=value){return `<div class="hud-cell"><span class="hud-label">${label}</span><span class="hud-value">${value}</span>${max?`<div class="meter"><i style="width:${Math.max(0,Math.min(100,numeric/max*100))}%"></i></div>`:''}</div>`;}
function render(state,env,status='已保存'){if(!state){view('home');$('save-status').textContent=status;return;}if(state.phase==='ended'){renderEnding(state);return;}view('game');$('save-status').textContent=status;const p=state.player,slot=state.clock.slotIndex,day=slot<5?'D1':'D2',times=['清晨','上午','下午','黄昏','夜晚'],time=times[slot%5]||'封锁';const loc=Game.content.locations.find(x=>x.id===state.locationId);const ap=slot<10?5-slot%5:0;
$('hud').innerHTML=bar('日程 / 时段',`${day} · ${time}`)+bar('剩余时段',String(ap),'5')+bar('生命 / HP',`${p.hp}/${p.maxHp}`,p.maxHp,p.hp)+bar('理智 / SAN',`${p.san}/${p.maxSan}`,p.maxSan,p.san)+bar('体力 / STA',`${p.sta}/${p.maxSta}`,p.maxSta,p.sta)+(state.settings.showInf?bar('感染 / INF',`${p.inf}%`,100,p.inf):bar('感染状态',p.inf>=75?'高危':p.inf>=25?'发热':'稳定'));
 $('character-panel').innerHTML=`<div class="panel-block"><h3 class="panel-title">SURVIVOR / 幸存者</h3><p><strong>${esc(p.name)}</strong> · ${esc(({citizen:'普通市民',medic:'医护人员',mechanic:'维修工'})[p.origin])}</p><p>${esc(({steady:'沉着',hunter:'天生猎手',healer:'快速愈合',iron:'钢铁意志'})[p.trait]||p.trait)} · ${esc(({none:'无明显缺陷',old_injury:'旧伤',susceptible:'病毒易感',social:'社交障碍'})[p.flaw]||p.flaw)}</p>${p.personality?`<p>性格：${esc(p.personality)}</p>`:''}${p.goal?`<p>目标：${esc(p.goal)}</p>`:''}<p>技能点 SP：${p.sp}</p>${Object.entries(p.skills).map(([k,v])=>`<p>${S[k]} <span class="muted">${'●'.repeat(v)}${'○'.repeat(5-v)} · ${v}</span></p>`).join('')}<p class="muted">当前位置：${loc.name}</p></div>`;
 const task=state.tasks.main;$('task-panel').innerHTML=`<div class="panel-block"><h3 class="panel-title">ACTIVE OBJECTIVE / 当前目标</h3><p>${task.stage==='broadcast'?'接收并记录撤离广播':task.stage==='route'?'选择通行凭据路线或地下通道':task.stage==='credential'?'前往集合点，可执行最后救援':task.stage==='tunnel'?'打通地下通道':task.stage==='tunnel_open'?'沿通道抵达集合点':'确认撤离方式'}</p><p class="muted">D3 清晨封锁 · 进行中</p><p>医生支线：${esc(state.tasks.doctor.status)}　警员支线：${esc(state.tasks.police.status)}　技术支线：${esc(state.tasks.tech.status)}</p></div><div class="panel-block"><h3 class="panel-title">JOURNAL / 行动记录</h3>${state.journal.slice(0,5).map(x=>`<p class="muted">${esc(x)}</p>`).join('')}</div>`;
 $('people-panel').innerHTML=`<div class="panel-block"><h3 class="panel-title">COMPANIONS / 同伴</h3>${Object.values(state.companions.byId).map(c=>`<div class="companion-card"><h4>${esc(c.name)} · ${esc(c.role)} ${c.recruited?'· 已招募':'· 未同行'}</h4><p>${esc(c.goal)}</p><p>忠诚 ${c.loyalty} · 恐惧 ${c.fear}${!c.alive?' · 已死亡':''}</p>${c.recruited&&state.locationId==='safehouse'&&state.phase==='exploration'?`<button data-companion="${c.id}" ${state.companions.activeId===c.id?'disabled':''}>${state.companions.activeId===c.id?'当前同行':'设为同行'}</button>`:''}</div>`).join('')}<p>幸存者关系 ${state.relations.survivors} · 警员 ${state.relations.police} · 交易者 ${state.relations.traders}</p></div>`;
 const map=Game.content.locations.map(l=>{const cur=l.id===state.locationId,adj=Game.content.neighbors[state.locationId]?.includes(l.id),blocked=l.id==='assembly'&&!state.inventory.pass&&!state.world.flags.tunnel_open;return `<div class="location-card"><i class="loc-dot ${cur?'current':''}"></i>${cur?`<span>${l.name} · 你在这里</span>`:`<button class="loc-link" data-move="${l.id}" ${!adj||blocked||state.phase!=='exploration'?'disabled':''}><span>${l.name}</span><small>${blocked&&l.id==='assembly'?'需通行证/通道':adj?'移动 · 1 时段':'不可达'}</small></button>`}</div>`;}).join('');$('map-panel').innerHTML=`<div class="panel-block"><h3 class="panel-title">PERIMETER MAP / 周边地图</h3>${map}<p class="muted">路线：警戒站通行证 / 地下通道。直接移动到集合点需要其一。</p></div>`;
 const load=Object.entries(state.inventory).reduce((n,[id,count])=>n+(Game.content.items.find(x=>x.id===id)?.w||0)*count,0)/1000;$('inventory-panel').innerHTML=`<div class="panel-block"><h3 class="panel-title">FIELD KIT / 背包 <span class="muted">${load.toFixed(1)} / 12 kg</span></h3>${Object.entries(state.inventory).filter(([,n])=>n>0).map(([id,n])=>`<div class="item-row"><span>${T[id]||id} ×${n}</span>${['bandage','medkit','suppressant'].includes(id)?`<button data-use="${id}" ${state.phase!=='exploration'||(id!=='suppressant'&&p.hp===p.maxHp)?'disabled':''}>使用</button>`:''}</div>`).join('')}${state.locationId==='safehouse'&&state.phase==='exploration'?`<div class="action-list">${Game.content.recipes.map(r=>`<button class="action-btn" data-craft="${r.id}">制造 ${r.name}<small>1 时段 · ${Object.entries(r.in).map(([i,n])=>`${T[i]}×${n}`).join(' + ')}${r.doc?' · 需要情报':''}</small></button>`).join('')}<button class="action-btn" data-rest>休息<small>恢复 HP +10 / SAN +10 / STA +40 · 1 时段</small></button></div>`:''}</div>`;
 $('story-content').innerHTML=['event','combat'].includes(state.phase)?renderEvent(state):renderExplore(state,loc);$('action-list').innerHTML=state.phase==='event'?renderChoices(state):renderActions(state);activateTab(document.querySelector('.mobile-tabs .active')?.dataset.tab||'story');
}
function renderEvent(s){if(s.phase==='combat'&&s.combat){const enemy=Game.content.enemies.find(x=>x.id===s.combat.enemyId);return `<div class="story-meta">COMBAT · 回合 ${s.combat.turn}</div><h2>${esc(enemy.name)} <span class="status-tag">HP ${s.combat.enemyHp}/${enemy.hp}</span></h2><p class="story-body">${esc(enemy.weakness)}。敌人逼近，下一次攻击会造成 ${enemy.attack} 点伤害。弹药 ${s.inventory.ammo} 发。</p><div class="result-box">每个有效指令解决一个完整回合。敌人倒下后不会反击；刷新后会从这个回合继续。</div>`;}const e=Game.content.events[s.activeEvent?.eventId];if(!e)return `<div class="story-meta">ACTION IN PROGRESS</div><h2>行动进行中</h2><p class="story-body">当前行动将在完成后推进一个时段。</p>`;const loc=Game.content.locations.find(x=>x.id===s.locationId);return `<div class="story-meta">${esc(loc.name)} · ${s.clock.slotIndex<5?'D1':'D2'} / ${['清晨','上午','下午','黄昏','夜晚'][s.clock.slotIndex%5]}</div><h2>${esc(e.title||loc.name)}</h2><p class="story-body">${esc(e.text)}</p>${s.player.san<30?'<div class="result-box">理智偏低：当前感知可能不可靠。实际资源变化仍会明确显示。</div>':''}`;}
function renderChoices(s){const e=Game.content.events[s.activeEvent?.eventId];if(!e)return '<p>等待行动结算</p>';return e.choices.map(c=>{let disabled=false,reason=`完成后推进 1 个时段`;if(s.world.eventRecords[c.id]&&!Game.content.randomEvents.some(x=>x.id===s.activeEvent.eventId)){disabled=true;reason='此选项已完成';}if(c.requires?.item&&!s.inventory[c.requires.item]){disabled=true;reason=`缺少${T[c.requires.item]||c.requires.item}`;}if(c.requires?.doc&&!s.world.documents.includes(c.requires.doc)){disabled=true;reason='缺少路线记录';}if(c.requires?.flag&&!s.world.flags[c.requires.flag]){disabled=true;reason='尚未取得相关线索';}if(c.id.startsWith('rescue')&&!s.companions.activeId){disabled=true;reason='需要招募一名同行者协助救援';}const warning=s.settings.endingHints&&c.effects?.some(x=>x.type==='ending')?' · 将触发终局':'';return `<button class="action-btn" data-choice="${c.id}" ${disabled?'disabled':''}><span>${esc(c.label)} <span class="arr">→</span></span><small>${reason}${warning}</small></button>`;}).join('');}
function renderExplore(s,l){return `<div class="story-meta">${esc(l.name)} · ${s.clock.slotIndex<5?'D1':'D2'} / ${['清晨','上午','下午','黄昏','夜晚'][s.clock.slotIndex%5]}</div><h2>${esc(l.name)}</h2><p class="story-body">${esc(l.desc)}</p><div class="result-box">当前目标：${s.tasks.main.stage==='broadcast'?'先记录广播':s.tasks.main.stage==='route'?'找到可行的撤离路线':s.tasks.main.stage==='tunnel'?'调查并打通地下路线':'前往集合点'}。你可以查看地图、整理背包，或直接移动到相邻地点。</div>${s.clock.slotIndex>=9?'<p class="danger-text">最后一个时段即将结束。完成当前行动前先确认撤离路线。</p>':''}`;}
function renderActions(s){if(s.phase==='combat'){return ['shoot','aim','defend','dodge','melee','reload','flee'].map(a=>`<button class="action-btn" data-combat="${a}" ${(a==='shoot'&&(s.weapon.magazine<=0||s.weapon.durability<=0))?'disabled':''}>${({shoot:'射击',aim:'瞄准',defend:'防御',dodge:'闪避',melee:'近战',reload:'换弹',flee:'逃跑'})[a]}<small>${a==='shoot'?`弹匣 ${s.weapon.magazine}/${s.weapon.capacity} · 备用 ${s.inventory.ammo} · 耐久 ${s.weapon.durability}/${s.weapon.maxDurability}`:a==='aim'?'下次射击阈值 +15':a==='defend'?'本回合伤害减半':a==='flee'?'失败后敌人仍会攻击':'消耗一个战斗回合'}</small></button>`).join('');}if(s.phase!=='exploration')return '';let buttons=`<button class="action-btn" data-endday>结束当天 <span class="arr">→</span><small>跳过剩余时段；已知截止与日终结算仍会执行</small></button>`;const eligible=Game.content.randomEvents.some(x=>x.location===s.locationId&&!s.world.eventRecords[`count:${x.id}`]);if(s.settings.randomEvents&&eligible)buttons+=`<button class="action-btn" data-explore>调查周边 <span class="arr">→</span><small>随机事件 · 1 个时段 · 按地点抽取固定内容</small></button>`;if(s.locationId==='checkpoint')buttons+=`<button class="action-btn" data-trade="medicine">以口粮换药剂<small>支付口粮 ×1，获得药剂 ×1 · 1 个时段</small></button><button class="action-btn" data-trade="food">以饮用水换口粮<small>支付水 ×1，获得口粮 ×1 · 1 个时段</small></button>`;if(s.locationId==='safehouse'&&s.player.sp>0)buttons+=`<button class="action-btn" data-train="combat">训练战斗技能<small>花费 ${s.player.skills.combat+1} SP · 1 个时段</small></button>`;return buttons;}
function renderEnding(s){view('ending');const end=Game.content.endings.find(x=>x.id===s.outcome.id);$('ending-title').textContent=end?.name||'结局';$('ending-copy').textContent=s.outcome.summary;$('ending-details').innerHTML=`<div class="ending-facts"><p><b>人物记录</b> · ${esc(s.player.name)} · ${esc(s.player.age)} 岁</p><p>${esc(s.outcome.reason)} · 最终时段 D${Math.floor(s.clock.slotIndex/5)+1}</p><p>同行者：${s.companions.activeId?esc(s.companions.byId[s.companions.activeId].name):'无'}</p><p>已发现情报：${s.world.documents.length} 份 · 当前任务：${esc(s.tasks.main.stage)}</p><p>已完成结局图鉴：${(Game.currentProfile?.endings||[]).map(x=>Game.content.endings.find(e=>e.id===x)?.name||x).join('、')||'尚无'}</p></div>`;}
function activateTab(tab){const grid=document.querySelector('.game-grid');if(grid)grid.dataset.tab=tab;document.querySelectorAll('.mobile-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));}
function modal(title,html,actions=[]){const d=$('modal'),opener=document.activeElement;$('modal-title').textContent=title;$('modal-content').innerHTML=html;$('modal-actions').replaceChildren(...actions.map(({label,run,primary=false})=>{const b=document.createElement('button');b.className=primary?'primary':'secondary';b.textContent=label;b.type='button';b.addEventListener('click',()=>{run?.();d.close();opener?.focus?.();});return b;}));if(!d.open)d.showModal();}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
Game.ui={$,view,render,modal,toast,activateTab,T,esc};
})();
